const left=['GPIO0','GPIO1','GND','GPIO2','GPIO3','GPIO4','GPIO5','GND.1','GPIO6','GPIO7','GPIO8','GPIO9','GND.2','GPIO10','GPIO11','GPIO12','GPIO13','GND.3','GPIO14','GPIO15'];
const right=['VBUS','VSYS','GND.4','3V3_EN','3V3','ADC_VREF','GPIO28','AGND','GPIO27','GPIO26','RUN','GPIO22','GND.5','GPIO21','GPIO20','GPIO19','GPIO18','GND.6','GPIO17','GPIO16'];
const pins=[...left.map((id,i)=>({id,x:6,y:16+i*9.6,side:'left',physical:i+1})),...right.map((id,i)=>({id,x:79,y:16+i*9.6,side:'right',physical:40-i}))].map(p=>({...p,name:p.id.replace('GPIO','GP').replace(/GND\.\d/,'GND'),net:p.id.startsWith('GND')||p.id==='AGND'?'GND':p.id,...(p.id.startsWith('GPIO')?{port:'GPIO',bit:+p.id.slice(4),digital:+p.id.slice(4),...(+p.id.slice(4)>=26?{analog:+p.id.slice(4)-26}:{})}:p.id==='3V3'||p.id==='ADC_VREF'?{voltage:3.3}:p.id==='VBUS'||p.id==='VSYS'?{voltage:5}:p.id.startsWith('GND')||p.id==='AGND'?{voltage:0}:{})}));
const models=[['pico','Raspberry Pi Pico',false,false,false],['pico-h','Raspberry Pi Pico H',false,true,false],['pico-w','Raspberry Pi Pico W',false,false,true],['pico-wh','Raspberry Pi Pico WH',false,true,true],['pico-2','Raspberry Pi Pico 2',true,false,false],['pico-2-headers','Raspberry Pi Pico 2 with headers',true,true,false],['pico-2-w','Raspberry Pi Pico 2 W',true,false,true],['pico-2-w-headers','Raspberry Pi Pico 2 W with headers',true,true,true]];
export const PICO_BOARDS=Object.fromEntries(models.map(([id,name,gen2,headers,wireless])=>[id,{id,name,architecture:'pico',mcu:gen2?'RP2350':'RP2040',cpu:gen2?'Cortex-M33':'Cortex-M0+',hz:gen2?150000000:125000000,ram:(gen2?520:264)*1024,flashSize:(gen2?4:2)*1024*1024,flashLimit:(gen2?4:2)*1024*1024,ioVoltage:3.3,logicHigh:2.31,supplyPin:'3V3',width:85,height:216,pins,gpio:pins.filter(p=>p.port).map(p=>p.digital),leds:{},asset:id+'.svg',headers,wireless,uart:'UART0 · GP0 TX / GP1 RX',source:'https://www.raspberrypi.com/documentation/microcontrollers/pico-series.html'}]));
export const isPicoBoard=id=>Object.hasOwn(PICO_BOARDS,id);
